mapper.select:
SELECT id, underpass_id, level, risk_score_min, updated_by, updated_at
  FROM threshold
 WHERE underpass_id = #{underpassId}
   AND level = #{level}

mapper.update:
UPDATE threshold
   SET risk_score_min = #{riskScoreMin},
       updated_by = #{updatedBy},
       updated_at = NOW()
 WHERE underpass_id = #{underpassId}
   AND level = #{level}
